178: ## Domain Events & Integration
179: 
180: ### Event-Driven Communication
181: ```typescript
182: // core$shared$domain-events/
183: abstract class DomainEvent {
184:   public readonly eventId: string;
185:   public readonly aggregateId: string;
186:   public readonly occurredOn: Date;
187:   public readonly eventVersion: number;
188: 
189:   constructor(aggregateId: string) {
190:     this.eventId = crypto.randomUUID();
191:     this.aggregateId = aggregateId;
192:     this.occurredOn = new Date();
193:     this.eventVersion = 1;
194:   }
195: }
196: 
197: // Task domain events
198: export class TaskAssignedEvent extends DomainEvent {
199:   constructor(
200:     taskId: string,
201:     public readonly agentId: string,
202:     public readonly priority: Priority
203:   ) {
204:     super(taskId);
205:   }
206: }
207: 
208: export class TaskCompletedEvent extends DomainEvent {
209:   constructor(
210:     taskId: string,
211:     public readonly result: TaskResult,
212:     public readonly duration: number
213:   ) {
214:     super(taskId);
215:   }
216: }
217: 
218: // Event handlers
219: @EventHandler(TaskCompletedEvent)
220: export class TaskCompletedHandler {
221:   constructor(
222:     private metricsRepository: IMetricsRepository,
223:     private sessionService: SessionLifecycleService
224:   ) {}
225: 
226:   async handle(event: TaskCompletedEvent): Promise<void> {
227:     // Update metrics
228:     await this.metricsRepository.recordTaskCompletion(
229:       event.aggregateId,
230:       event.duration
231:     );
232: 
233:     // Update session state
234:     await this.sessionService.markTaskCompleted(
235:       event.aggregateId,
236:       event.result
237:     );
238:   }
239: }
240: ```
